func TestIsOnMainBranch(t *testing.T) {
	t.Run("on main branch", func(t *testing.T) {
		tmpDir := t.TempDir()
		repo, err := git.PlainInit(tmpDir, false)
		if err != nil {
			t.Fatalf("failed to init repo: %v", err)
		}

		// Create initial commit on main
		testFile := filepath.Join(tmpDir, "test.txt")
		if err := os.WriteFile(testFile, []byte("test"), 0o644); err != nil {
			t.Fatalf("failed to write test file: %v", err)
		}

		wt, err := repo.Worktree()
		if err != nil {
			t.Fatalf("failed to get worktree: %v", err)
		}

		if _, err := wt.Add("test.txt"); err != nil {
			t.Fatalf("failed to add file: %v", err)
		}

		if _, err := wt.Commit("Initial commit", &git.CommitOptions{
			Author: &object.Signature{Name: "Test", Email: "test@example.com"},
		}); err != nil {
			t.Fatalf("failed to commit: %v", err)
		}

		// Rename master to main (go-git creates master by default)
		head, _ := repo.Head()
		ref := plumbing.NewHashReference(plumbing.NewBranchReferenceName("main"), head.Hash())
		if err := repo.Storer.SetReference(ref); err != nil {
			t.Fatalf("failed to create main branch: %v", err)
		}
		if err := wt.Checkout(&git.CheckoutOptions{Branch: plumbing.NewBranchReferenceName("main")}); err != nil {
			t.Fatalf("failed to checkout main: %v", err)
		}

		if !IsOnMainBranch(repo) {
			t.Error("IsOnMainBranch() = false, want true when on main branch")
		}
	})

	t.Run("on master branch", func(t *testing.T) {
		tmpDir := t.TempDir()
		repo, err := git.PlainInit(tmpDir, false)
		if err != nil {
			t.Fatalf("failed to init repo: %v", err)
		}

		// Create initial commit (go-git defaults to master)
		testFile := filepath.Join(tmpDir, "test.txt")
		if err := os.WriteFile(testFile, []byte("test"), 0o644); err != nil {
			t.Fatalf("failed to write test file: %v", err)
		}

		wt, err := repo.Worktree()
		if err != nil {
			t.Fatalf("failed to get worktree: %v", err)
		}

		if _, err := wt.Add("test.txt"); err != nil {
			t.Fatalf("failed to add file: %v", err)
		}

		if _, err := wt.Commit("Initial commit", &git.CommitOptions{
			Author: &object.Signature{Name: "Test", Email: "test@example.com"},
		}); err != nil {
			t.Fatalf("failed to commit: %v", err)
		}

		if !IsOnMainBranch(repo) {
			t.Error("IsOnMainBranch() = false, want true when on master branch")
		}
	})

	t.Run("on feature branch", func(t *testing.T) {
		tmpDir := t.TempDir()
		repo, err := git.PlainInit(tmpDir, false)
		if err != nil {
			t.Fatalf("failed to init repo: %v", err)
		}

		// Create initial commit
		testFile := filepath.Join(tmpDir, "test.txt")
		if err := os.WriteFile(testFile, []byte("test"), 0o644); err != nil {
			t.Fatalf("failed to write test file: %v", err)
		}

		wt, err := repo.Worktree()
		if err != nil {
			t.Fatalf("failed to get worktree: %v", err)
		}

		if _, err := wt.Add("test.txt"); err != nil {
			t.Fatalf("failed to add file: %v", err)
		}

		if _, err := wt.Commit("Initial commit", &git.CommitOptions{
			Author: &object.Signature{Name: "Test", Email: "test@example.com"},
		}); err != nil {
			t.Fatalf("failed to commit: %v", err)
		}

		// Create and checkout feature branch
		head, _ := repo.Head()
		if err := wt.Checkout(&git.CheckoutOptions{
			Hash:   head.Hash(),
			Branch: plumbing.NewBranchReferenceName("feature/test"),
			Create: true,
		}); err != nil {
			t.Fatalf("failed to checkout feature branch: %v", err)
		}

		if IsOnMainBranch(repo) {
			t.Error("IsOnMainBranch() = true, want false when on feature branch")
		}
	})
}

content.text:
You're right - we're relying on the `main`/`master` naming convention. That's what `GetMainBranchHash()` already does:

```go
// From common.go:1244
func GetMainBranchHash(repo *git.Repository) plumbing.Hash {
    for _, branchName := range []string{"main", "master"} {
        // Try local branch first, then remote tracking
        ...
    }
    return plumbing.ZeroHash
}
```

So `IsOnMainBranch` would just check if `GetCurrentBranchName()` returns `"main"` or `"master"`.

**Limitation**: If someone uses a different default branch (e.g., `trunk`, `develop`), this won't work correctly. 

**Options:**
1. **Convention-based** (simple): Check for `main`/`master` - matches existing `GetMainBranchHash` pattern
2. **Config-based**: Read from git config (`init.defaultBranch`) or add an Entire setting
3. **Remote-based**: Check what `origin/HEAD` points to (if available)

For now, option 1 is consistent with what we already do. We could add smarter detection later.

Should I proceed with the convention-based approach, or would you prefer to add config/remote detection?

