	if _, err := repo.Reference(plumbing.NewBranchReferenceName("main"), true); err == nil {
		return "main"
	}
	if _, err := repo.Reference(plumbing.NewBranchReferenceName("master"), true); err == nil {
		return "master"
	}

	return ""
}

