// hasCodeChanges checks if a commit has any changes outside of .entire/ metadata directory.
// Returns true if there are code changes (not just metadata), false if only metadata changed.
func hasCodeChanges(commit *object.Commit) bool {
	// Get commit tree
	commitTree, err := commit.Tree()
	if err != nil {
		return true // Assume has changes on error
	}

	// Get parent tree (if no parent, assume this is meaningful)
	if commit.NumParents() == 0 {
		return true
	}

	parent, err := commit.Parent(0)
	if err != nil {
		return true // Assume has changes on error
	}

	parentTree, err := parent.Tree()
	if err != nil {
		return true // Assume has changes on error
	}

	// Diff the trees
	changes, err := parentTree.Diff(commitTree)
	if err != nil {
		return true // Assume has changes on error
	}

	// Check if any change is outside .entire/
	for _, change := range changes {
		name := change.To.Name
		if name == "" {
			name = change.From.Name
		}
		// If any file is NOT in .entire/, there are code changes
		if !strings.HasPrefix(name, ".entire/") {
			return true
		}
	}

	return false // Only .entire/ files changed
}

